written = []
for cid, obj in P.items():
    with open(os.path.join(OUT, cid + ".json"), "w", encoding="utf-8") as f:
        json.dump(obj, f, ensure_ascii=False, indent=1)
    written.append(cid)

# self-verify
import glob
ok = 0
counts = {"changed_main": 0, "reserve_used": 0, "disputed": 0}
for cid in written:
    d = json.load(open(os.path.join(OUT, cid + ".json"), encoding="utf-8"))
    assert d["case_id"] == cid
    assert set(["case_id","prediction_text","basis","confidence","trigger"]).issubset(d.keys())
    assert 0 <= d["confidence"] <= 1
    t = d["trigger"]
    assert set(["changed_main","reserve_used","disputed","reason"]).issubset(t.keys())
    counts["changed_main"] += bool(t["changed_main"])
    counts["reserve_used"] += bool(t["reserve_used"])
    counts["disputed"] += bool(t["disputed"])
    ok += 1
print("written:", ok, "ids:", ",".join(sorted(written)))
print("trigger_counts:", counts)
